INSERT INTO `site_contents` VALUES ('6a745ce03650f51f49aa5e11','education','[{\"desc\": \"主修课程：数据结构、计算机组成原理、操作系统、计算机网络、Web开发技术\", \"year\": \"2024.9 – 至今\", \"title\": \"软件工程\", \"school\": \"广东财经大学\"}]','2026-08-06 18:07:29','2026-08-25 19:20:36'),('6a745ce13650f51f49aa5e12','skills','[\"熟悉HTML5、CSS3、JavaScript(ES6+)/TypeScript，了解HTTP协议以及事件循环，浏览器渲染等前端核心原理\", \"熟练掌握React函数式组件开发，熟练运用Hooks，Zustand，React Router等相关生态，了解Next.js及Vue3，并有实际项目经验\", \"熟练使用 Vite 进行项目构建，可以熟练用 Git 协作开发 及 npm/pnpm 依赖管理；了解 Docker 容器化部署\", \"具备工程化代码规范意识，使用 ESLint + Prettier统一代码风格，利用 TypeScript + Zod 保障代码健壮性\", \"了解 Node.js + Express 服务端开发及 MySQL 数据库操作；掌握 WebSocket 实现实时数据通信\", \"了解Tailwind Css与Ant Design，Echarts等常用组件库与工具，具备快速查阅官方文档解决问题的能力\", \"善于借助Claude Code，Codex等AI编程工具进行高效开发，代码优化与问题排查\"]','2026-08-06 18:07:29','2026-08-29 20:23:46'),('6a745ce13650f51f49aa5e13','resumeProjects','[{\"desc\": [\"实现多方式数据导入：内置 3 个预标注舆情场景(1300+条)/ 粘贴 / CSV / URL 定时抓取四种来源，CSV支持中英文表头与情感列别名自适应，外部 ID → 显式字段全重合两级去重，杜绝重复数据污染告警与统计\", \"设计批量分析引擎：8 条/批调用大模型（请求数降为 1/8）、6 个 worker 并发限流，断点续跑 + 批量失败自动降级单条重试，支持暂停/恢复/取消，进度经 WebSocket 实时推送\", \"搭建 ECharts 实时监控大盘：情感环形图 / 按天趋势 / 热门主题 / 关键词词云四图联动，支持主题钻取与近 7天时段对比，统一封装初始化/自适应缩放/销毁\", \"实现智能告警引擎：负面率 / 评论量 / 敏感关键词三类规则 + 滑动窗口 Z-score 异常检测（|z|≥2 触发，基线排除当前值）+ 60s冷却防抖，异常秒级弹窗\", \"封装 socket.io 实时链路：断线自动重连并重新订阅，配合 1-20 倍速评论模拟器按时间轴回放，负面激增时告警弹窗即时弹出\", \"基于 fetch + ReadableStream 解析 SSE 流式响应，落地五段式 AI 舆情周报逐字渲染、随时可中断，一键导出 Markdown\"], \"meta\": \"2026.7 – 2024.9 · React · TypeScript · Next.js · Express · MySQL · ECharts · OpenAPI\", \"title\": \"AI 评论分析与舆情监控平台\"}, {\"desc\": [\"内容页采用 SSG + ISR 混合渲染，正文构建时预渲染进 HTML 实现首屏直出，访问走静态资源、降低后端请求压力；配合 on-demand\\nrevalidate 实现发文章即更新\", \"开发 MDX 编辑器：选区语法包裹、图片上传即插、实时预览，文章由服务端编译消毒后渲染，兼顾性能与存储型 XSS 防护\", \"落地一键总结、划词解释、多轮追问三个 AI 交互：划词取词、会话上下文拼接，流式回答随时中断，降低长文阅读成本\", \"实现嵌套评论与点赞：评论按 parentId 组织无限层级并自动折叠，点赞经事务 + 行锁保证原子切换，前端乐观更新即时反馈\", \"设计 JWT 双角色认证：token 校验回查数据库支持吊销，配合 bcrypt 哈希与敏感字段脱敏，支撑登录态与权限路由\"], \"meta\": \"2026.5 – 2024.9 · React · TypeScript · Next.js · Express · MySQL · MDX · OpenAPI\", \"title\": \"个人主页\"}]','2026-08-06 18:07:29','2026-08-30 09:48:52'),('6a745ce13650f51f49aa5e14','evaluation','\"热爱前端开发，主动跟进React生态、Node全栈等前沿技术，持续关注行业发展趋势；对AI应用抱有浓厚兴趣，擅长借助AI辅助代码编写、接口设计、问题调试；能够独立校验AI产出、梳理逻辑并落地完整项目，善用工具提升开发效率，保持自主思考不盲目照搬生成内容。\"','2026-08-06 18:07:29','2026-08-06 18:07:29'),('6a745ce13650f51f49aa5e15','homeProjects','[{\"desc\": \"AI 评论分析与舆情监控平台 —— 导入用户评论，AI 批量分析情感/主题/关键词，可视化监控并自动告警、生成周报\", \"link\": \"https://github.com/luo6667/InsightScope\", \"name\": \"InsightScope\", \"tags\": [\"React19\", \"Ts\", \"Next.js\", \"Node.js\", \"express\"]}, {\"desc\": \"一个采用前后端的个人主页项目，前端React19+ts，后端为express，主要分为首页，博客，简历，关于四部分\", \"link\": \"https://github.com/luo6667/Personal-Page\", \"name\": \"个人页面\", \"tags\": [\"React19\", \"Ts\", \"Next.js\", \"Node.js\", \"express\"]}, {\"desc\": \"可以获取用户交互事件的一个网站，用于分析用户的兴趣以及对页面的哪部分关注度更高\", \"link\": \"https://github.com/luo6667/User-Behavior-Heatmap-AnalysisPlatform\", \"name\": \"User-Behavior-Heatmap-AnalysisPlatform\", \"tags\": [\"React19\", \"Ts\", \"Node.js\", \"express\"]}, {\"desc\": \"一个适合初学者的reactTodoList，包含react19，ts，以及zod，Tanstack Query，zustand等，并在关键地方给予注释\", \"link\": \"https://github.com/luo6667/TodoList\", \"name\": \"TodoList待办清单\", \"tags\": [\"React19\", \"Ts\", \"zod\", \"TanstackQuery\", \"zustand\"]}, {\"desc\": \"一个React+Ts的小项目\", \"link\": \"https://github.com/luo6667/-\", \"name\": \"极客园移动端\", \"tags\": [\"React19\", \"Ts\"]}, {\"desc\": \"一个模仿b站页面以及基本功能的前端项目\", \"link\": \"https://github.com/luo6667/-b-\", \"name\": \"仿b站前端\", \"tags\": [\"Vue3\", \"Pinia\"]}, {\"desc\": \"集待办事项-资源搜索-任务规划为一体的个人学习工作台,内有ai可以给予学习规划\", \"link\": \"https://github.com/luo6667/personal-Learning-Workbench\", \"name\": \"个人学习工作台\", \"tags\": [\"Vue3\", \"Pinia\"]}, {\"desc\": \"一个电商平台，实现了基本的电商网站的功能\", \"link\": \"https://github.com/luo6667/vue3Rabbit\", \"name\": \"小兔鲜\", \"tags\": [\"Vue3\", \"axios\", \"Pinia\"]}]','2026-08-06 18:07:29','2026-08-25 19:13:04'),('bcbe74a3029c5163b3cbbc1d','plan','[{\"goals\": [{\"desc\": \"掌握 Flex / Grid、移动端适配与常见页面布局方案。\", \"tags\": [\"HTML\", \"CSS\"], \"title\": \"HTML / CSS 布局与响应式\", \"status\": \"done\"}, {\"desc\": \"闭包、原型链、异步与模块化，能手写常见工具函数。\", \"tags\": [\"JavaScript\"], \"title\": \"JavaScript 核心与 ES6+\", \"status\": \"done\"}, {\"desc\": \"分支管理、提交规范与代码评审流程。\", \"tags\": [\"Git\"], \"title\": \"Git 与命令行工作流\", \"status\": \"done\"}], \"title\": \"打基础：HTML / CSS / JavaScript\", \"period\": \"2024.9 – 2025.6\", \"status\": \"done\", \"summary\": \"把三件套、浏览器基础与 Git 工作流练熟，能独立完成响应式静态页面。\"}, {\"goals\": [{\"desc\": \"组件拆分、Hooks、zustand 与 React Query 的数据流设计。\", \"tags\": [\"React\", \"TypeScript\"], \"title\": \"React 组件化与状态管理\", \"status\": \"done\"}, {\"desc\": \"服务端组件、路由组织、静态化与按需 revalidate。\", \"tags\": [\"Next.js\"], \"title\": \"Next.js App Router 与 SSR / ISR\", \"status\": \"active\"}, {\"desc\": \"Express 分层、Sequelize 建模、鉴权与部署。\", \"tags\": [\"Node.js\", \"MySQL\"], \"title\": \"Node + MySQL 全栈闭环\", \"status\": \"active\"}, {\"desc\": \"ESLint / Prettier / 类型检查 + 自动化部署流水线。\", \"tags\": [\"CI/CD\"], \"title\": \"工程规范与 CI/CD\", \"status\": \"planned\"}], \"title\": \"进阶：React 生态与全栈项目\", \"period\": \"2025.7 – 2026.6\", \"status\": \"active\", \"summary\": \"以 React + TypeScript 为主线，完成一个可上线的全栈项目并沉淀工程规范。\"}, {\"goals\": [{\"desc\": \"重排重绘、首屏指标、打包体积与缓存策略。\", \"tags\": [\"Performance\"], \"title\": \"浏览器渲染与性能优化\", \"status\": \"planned\"}, {\"desc\": \"ECharts / D3 图表封装与大数据量渲染优化。\", \"tags\": [\"可视化\"], \"title\": \"数据可视化实战\", \"status\": \"planned\"}, {\"desc\": \"跟着调度器与打包流程读源码，并整理成笔记。\", \"tags\": [\"源码\"], \"title\": \"源码阅读：React 与构建工具\", \"status\": \"planned\"}], \"title\": \"深入：原理、性能与可视化\", \"period\": \"2026.7 – 2027.6\", \"status\": \"planned\", \"summary\": \"从会用走向理解，补齐浏览器原理、性能优化与数据可视化能力。\"}, {\"goals\": [{\"desc\": \"提示工程、流式对话、RAG 与工具调用的落地经验。\", \"tags\": [\"AI\"], \"title\": \"AI 应用与 Agent 实践\", \"status\": \"planned\"}, {\"desc\": \"保持博客更新，给用到的开源项目提 PR。\", \"tags\": [\"开源\"], \"title\": \"持续输出与开源贡献\", \"status\": \"planned\"}], \"title\": \"长期：AI 应用与开源\", \"period\": \"2027 以后\", \"status\": \"planned\", \"summary\": \"把 AI 能力做成产品，参与开源，形成自己的技术表达。\"}]','2026-11-10 14:42:31','2026-11-10 14:42:31');
